from fractions import Fraction

def is_rational_square(q: Fraction) -> bool:
    """Checks if a positive rational number q is the square of a rational number."""
    if q <= 0:
        return False

    # Reduce to lowest terms p/r
    p = q.numerator
    r = q.denominator

    # Check if both numerator and denominator are perfect squares
    import math
    def is_perfect_square(n):
        if n < 0:
            return False
        sqrt_n = int(math.isqrt(n))
        return sqrt_n * sqrt_n == n

    return is_perfect_square(p) and is_perfect_square(r)

def calculate_b_squared(a_val):
    """Calculates b^2 for a given rational a."""
    if a_val == 2:
        return None # Undefined

    a = Fraction(a_val)

    # b^2 = a^2 - a/(a-2)
    term2 = a / (a - 2)
    b_squared = a*a - term2
    return b_squared

test_values = [1, 0, -1, 3, -2, 1/2, 3/2]
results = {}

for a_val in test_values:
    b2 = calculate_b_squared(a_val)
    is_square = is_rational_square(b2) if b2 is not None else False

    results[a_val] = {
        'b^2': b2,
        'is_rational_square': is_square
    }

# Print results in a readable format
print("--- Calculation Results ---")
for a_val, res in results.items():
    print(f"a = {a_val}:")
    print(f"  b^2 = {res['b^2']}")
    print(f"  b^2 is a rational square: {res['is_rational_square']}")
